import React, { useCallback, useEffect, useState } from 'react';
import {
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  Legend,
  Pie,
  PieChart,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from 'recharts';
import {
  Button,
  FormActions,
  Input,
  dispatchAppToast,
} from '@linm-soft-org/linm-web-common-components';
import { Spin, Text, Title } from '@/components/common';
import { useAppDispatch } from '../../../store/hooks';
import { fpcService } from '../../../services/fpc/service';
import type { CashflowReportDto } from '../../../services/fpc/types';
import { useFpcPermissions } from '../../../utils/fpcPermissionCode';
import styles from './CeoCashTodayPage.module.css';

const TEST_ID = 'ceo-cash-today';

const fVnd = (v: number): string =>
  new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND', maximumFractionDigits: 0 }).format(v);

const fCompact = (v: number): string => {
  const abs = Math.abs(v);
  const sign = v < 0 ? '-' : '';
  if (abs >= 1_000_000_000) return `${sign}${(abs / 1_000_000_000).toFixed(1)} tỷ`;
  if (abs >= 1_000_000) return `${sign}${(abs / 1_000_000).toFixed(0)} tr`;
  if (abs >= 1_000) return `${sign}${(abs / 1_000).toFixed(0)} ng`;
  return `${v.toLocaleString('vi-VN')}`;
};

const chartCurrency = (v: number): string => `${(v / 1_000_000).toFixed(0)}tr`;

function todayLocalYmd(): string {
  const d = new Date();
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

function formatDisplayDate(isoOrYmd?: string | null): string {
  if (!isoOrYmd) return '—';
  const raw = isoOrYmd.slice(0, 10);
  const [y, m, d] = raw.split('-');
  if (!y || !m || !d) return isoOrYmd;
  return `${d}/${m}/${y}`;
}

const CeoCashTodayPage: React.FC = () => {
  const dispatch = useAppDispatch();
  const { canViewCeoDashboard, canExportReports } = useFpcPermissions();

  const [filterDate, setFilterDate] = useState(todayLocalYmd);
  const [appliedDate, setAppliedDate] = useState(todayLocalYmd);
  const [data, setData] = useState<CashflowReportDto | null>(null);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState(false);

  const loadReport = useCallback(async (date: string) => {
    setLoading(true);
    setLoadError(false);
    try {
      const result = await fpcService.getCashflow({ date });
      setData(result);
      setAppliedDate(date);
    } catch {
      setData(null);
      setLoadError(true);
      dispatchAppToast(dispatch, {
        message: 'Không thể tải báo cáo dòng tiền',
        type: 'error',
      });
    } finally {
      setLoading(false);
    }
  }, [dispatch]);

  useEffect(() => {
    const t = window.setTimeout(() => {
      void loadReport(appliedDate);
    }, 0);
    return () => window.clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps -- initial load only; Xem/Làm mới gọi loadReport
  }, []);

  const handleView = () => {
    if (!filterDate) {
      dispatchAppToast(dispatch, { message: 'Vui lòng chọn ngày xem', type: 'error' });
      return;
    }
    void loadReport(filterDate);
  };

  const handleRefresh = () => {
    void loadReport(appliedDate);
  };

  if (!canViewCeoDashboard) {
    return (
      <div className={styles.page} data-testid={`${TEST_ID}-page`}>
        <div className={styles.empty}>
          <Text type="secondary">Bạn không có quyền xem báo cáo dòng tiền.</Text>
        </div>
      </div>
    );
  }

  const netCashflow = data ? data.expectedInflow - data.expectedOutflow : 0;
  const warningCount = data?.alerts?.filter(a => a.severity === 'Warning' || a.severity === 'Critical').length ?? 0;
  const sortedBranches = data
    ? [...data.branchSummaries].sort((a, b) => b.netCashflow - a.netCashflow)
    : [];

  return (
    <div className={styles.page} data-testid={`${TEST_ID}-page`}>
      <div className={styles.headerCard}>
        <div className={styles.headerTop}>
          <div>
            <Title level={4}>
              <i className="fas fa-chart-pie" style={{ marginRight: 8, color: '#059669' }} />
              Báo cáo dòng tiền
            </Title>
            <Text type="secondary">
              Tổng quan tiền theo ngày · runway · cảnh báo
              {appliedDate ? ` · Ngày xem: ${formatDisplayDate(appliedDate)}` : ''}
            </Text>
          </div>
          <FormActions align="end">
            <Button onClick={handleRefresh} data-testid={`${TEST_ID}-refresh-btn`}>
              <i className="fas fa-redo" /> Làm mới
            </Button>
            {canExportReports && (
              <Button
                variant="secondary"
                disabled={!data}
                onClick={() => window.print()}
                data-testid={`${TEST_ID}-export-btn`}
              >
                <i className="fas fa-print" /> In
              </Button>
            )}
          </FormActions>
        </div>

        <div className={styles.filterRow}>
          <div className={styles.filterField}>
            <label className={styles.filterLabel} htmlFor={`${TEST_ID}-filter-date`}>Ngày xem</label>
            <Input
              id={`${TEST_ID}-filter-date`}
              type="date"
              value={filterDate}
              onChange={e => setFilterDate(e.target.value)}
              data-testid={`${TEST_ID}-filter-date`}
            />
          </div>
          <FormActions align="end">
            <Button variant="primary" onClick={handleView} data-testid={`${TEST_ID}-view-btn`}>
              <i className="fas fa-search" /> Xem
            </Button>
          </FormActions>
        </div>
      </div>

      {loading && (
        <div className={styles.loading} data-testid={`${TEST_ID}-loading`}>
          <Spin />
          <Text type="secondary">Đang tải báo cáo…</Text>
        </div>
      )}

      {!loading && loadError && (
        <div className={styles.empty} data-testid={`${TEST_ID}-error`}>
          <Text type="secondary">Không tải được dữ liệu. Thử Làm mới hoặc đổi ngày.</Text>
          <Button variant="primary" onClick={handleRefresh}>Thử lại</Button>
        </div>
      )}

      {!loading && !loadError && !data && (
        <div className={styles.empty} data-testid={`${TEST_ID}-empty`}>
          <Text type="secondary">Chưa có dữ liệu cho ngày đã chọn.</Text>
        </div>
      )}

      {!loading && data && (
        <div className={styles.contentPanel} data-testid={`${TEST_ID}-content`}>
          <div className={styles.statsRow}>
            <div className={styles.statCard}>
              <span className={styles.statLabel}>Tổng tiền</span>
              <span className={styles.statValue}>{fCompact(data.totalCash)}</span>
            </div>
            <div className={styles.statCard}>
              <span className={styles.statLabel}>Tiền khả dụng</span>
              <span className={`${styles.statValue} ${styles.positive}`}>{fCompact(data.availableCash)}</span>
            </div>
            <div className={styles.statCard}>
              <span className={styles.statLabel}>Số ngày an toàn</span>
              <span className={`${styles.statValue} ${styles.positive}`}>{data.runwayDays} ngày</span>
            </div>
            <div className={styles.statCard}>
              <span className={styles.statLabel}>Ngày đỏ gần nhất</span>
              <span className={`${styles.statValue} ${styles.warning}`}>
                {formatDisplayDate(data.nearestRedDate)}
              </span>
            </div>
          </div>

          <div className={styles.statsRow}>
            <div className={styles.statCard}>
              <span className={styles.statLabel}>Đầu ngày</span>
              <span className={styles.statValue}>{fCompact(data.openingBalance)}</span>
            </div>
            <div className={styles.statCard}>
              <span className={styles.statLabel}>Thu trong ngày</span>
              <span className={`${styles.statValue} ${styles.positive}`}>+{fCompact(data.expectedInflow)}</span>
            </div>
            <div className={styles.statCard}>
              <span className={styles.statLabel}>Chi trong ngày</span>
              <span className={`${styles.statValue} ${styles.negative}`}>-{fCompact(data.expectedOutflow)}</span>
            </div>
            <div className={styles.statCard}>
              <span className={styles.statLabel}>Dòng tiền thuần</span>
              <span className={`${styles.statValue} ${netCashflow >= 0 ? styles.positive : styles.negative}`}>
                {netCashflow >= 0 ? '+' : ''}{fCompact(netCashflow)}
              </span>
            </div>
          </div>

          <div className={styles.chartsRow}>
            <div className={styles.chartCard}>
              <div className={styles.chartCardHeader}>
                <h3 className={styles.chartTitle}>Cơ cấu tiền</h3>
                <span className={styles.sectionBadge}>Biểu đồ tròn</span>
              </div>
              {(data.composition?.length ?? 0) > 0 ? (
                <>
                  <ResponsiveContainer width="100%" height={280}>
                    <PieChart>
                      <Pie
                        data={data.composition}
                        dataKey="value"
                        nameKey="name"
                        cx="50%"
                        cy="50%"
                        innerRadius={60}
                        outerRadius={100}
                        paddingAngle={3}
                        label={({ name, percent }) => `${name} ${((percent ?? 0) * 100).toFixed(0)}%`}
                      >
                        {data.composition.map((entry, i) => (
                          <Cell key={`${entry.name}-${i}`} fill={entry.color || '#1677ff'} />
                        ))}
                      </Pie>
                      <Tooltip formatter={(v: number) => fVnd(v)} />
                    </PieChart>
                  </ResponsiveContainer>
                  <div className={styles.legendRow}>
                    {data.composition.map(entry => (
                      <div key={entry.name} className={styles.legendItem}>
                        <span className={styles.legendDot} style={{ background: entry.color }} />
                        <span>{entry.name}</span>
                        <strong>{fCompact(entry.value)}</strong>
                      </div>
                    ))}
                  </div>
                </>
              ) : (
                <Text type="secondary">Chưa có cơ cấu tiền.</Text>
              )}
            </div>

            <div className={styles.chartCard}>
              <div className={styles.chartCardHeader}>
                <h3 className={styles.chartTitle}>Dự kiến 7 ngày tới</h3>
                <span className={styles.sectionBadge}>Biểu đồ cột</span>
              </div>
              {(data.next7Days?.length ?? 0) > 0 ? (
                <ResponsiveContainer width="100%" height={280}>
                  <BarChart data={data.next7Days}>
                    <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" />
                    <XAxis
                      dataKey={(r: { date: string }) => {
                        const raw = String(r.date).slice(0, 10);
                        const [, m, d] = raw.split('-');
                        return `${d}/${m}`;
                      }}
                      tick={{ fontSize: 11 }}
                    />
                    <YAxis tickFormatter={chartCurrency} tick={{ fontSize: 11 }} />
                    <Tooltip formatter={(v: number) => fVnd(v)} />
                    <Legend />
                    <Bar dataKey="inflow" name="Thu" fill="#10b981" radius={[4, 4, 0, 0]} />
                    <Bar dataKey="outflow" name="Chi" fill="#f59e0b" radius={[4, 4, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              ) : (
                <Text type="secondary">Chưa có dữ liệu 7 ngày tới.</Text>
              )}
            </div>
          </div>

          <div className={styles.chartsRow}>
            <div className={styles.sectionCard}>
              <div className={styles.sectionHeader}>
                <h3 className={styles.sectionTitle}>Top chi nhiều nhất</h3>
                <span className={styles.sectionBadge}>{data.topOutflows?.length ?? 0} khoản</span>
              </div>
              {(data.topOutflows?.length ?? 0) > 0 ? (
                <div className={styles.tableWrapper}>
                  <table className={styles.table} data-testid={`${TEST_ID}-top-outflows`}>
                    <thead>
                      <tr>
                        <th>Danh mục</th>
                        <th className={styles.colRight}>Số tiền</th>
                        <th className={styles.colCenter}>Tỷ trọng</th>
                        <th>Phân bổ</th>
                      </tr>
                    </thead>
                    <tbody>
                      {data.topOutflows.map((item, i) => (
                        <tr key={`${item.category}-${i}`}>
                          <td>{item.category}</td>
                          <td className={styles.colAmount}>{fVnd(item.amount)}</td>
                          <td className={styles.colCenter}>{item.percent}%</td>
                          <td>
                            <div className={styles.barTrack}>
                              <div
                                className={styles.barFill}
                                style={{
                                  width: `${Math.min(100, Math.max(0, item.percent))}%`,
                                  background: i === 0 ? '#ef4444' : i === 1 ? '#f59e0b' : '#10b981',
                                }}
                              />
                            </div>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              ) : (
                <Text type="secondary">Chưa có khoản chi nổi bật.</Text>
              )}
            </div>

            <div className={styles.sectionCard}>
              <div className={styles.sectionHeader}>
                <h3 className={styles.sectionTitle}>Cảnh báo và thông báo</h3>
                <span className={styles.sectionBadge}>{warningCount} nghiêm trọng</span>
              </div>
              {(data.alerts?.length ?? 0) > 0 ? (
                <div data-testid={`${TEST_ID}-alerts`}>
                  {data.alerts.map((alert, i) => (
                    <div key={`${alert.title}-${i}`} className={styles.alertRow}>
                      <i
                        className={`fas ${alert.severity === 'Warning' || alert.severity === 'Critical' ? 'fa-exclamation-triangle' : 'fa-info-circle'}`}
                        style={{
                          fontSize: 16,
                          color: alert.severity === 'Critical' ? '#ef4444' : alert.severity === 'Warning' ? '#f59e0b' : '#3b82f6',
                          marginTop: 2,
                        }}
                      />
                      <div className={styles.alertBody}>
                        <div className={styles.alertTitleRow}>
                          <strong className={styles.alertTitle}>{alert.title}</strong>
                          <span className={styles.alertDate}>{alert.dateLabel || '—'}</span>
                        </div>
                        <p className={styles.alertMessage}>{alert.message}</p>
                      </div>
                    </div>
                  ))}
                </div>
              ) : (
                <Text type="secondary">Không có cảnh báo.</Text>
              )}
            </div>
          </div>

          <div className={styles.sectionCard}>
            <div className={styles.sectionHeader}>
              <h3 className={styles.sectionTitle}>Hiệu suất chi nhánh</h3>
              <span className={styles.sectionBadge}>{sortedBranches.length} cửa hàng</span>
            </div>
            {sortedBranches.length > 0 ? (
              <div className={styles.tableWrapper}>
                <table className={styles.table} data-testid={`${TEST_ID}-branches`}>
                  <thead>
                    <tr>
                      <th>#</th>
                      <th>Chi nhánh</th>
                      <th className={styles.colRight}>Thu</th>
                      <th className={styles.colRight}>Chi</th>
                      <th className={styles.colRight}>Dòng tiền thuần</th>
                    </tr>
                  </thead>
                  <tbody>
                    {sortedBranches.map((b, i) => (
                      <tr key={b.branchCode || b.branchName}>
                        <td>
                          <span
                            className={styles.phaseTag}
                            style={{
                              background: i < 3 ? '#d1fae5' : '#fef3c7',
                              color: i < 3 ? '#065f46' : '#92400e',
                            }}
                          >
                            #{i + 1}
                          </span>
                        </td>
                        <td>{b.branchName || b.branchCode}</td>
                        <td className={styles.colAmount}>{fVnd(b.expectedInflow ?? 0)}</td>
                        <td className={styles.colAmount}>{fVnd(b.expectedOutflow ?? 0)}</td>
                        <td className={`${styles.colAmount} ${b.netCashflow >= 0 ? styles.statusGreen : styles.statusRed}`}>
                          {b.netCashflow >= 0 ? '+' : ''}{fVnd(b.netCashflow ?? 0)}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            ) : (
              <Text type="secondary">Chưa có dữ liệu chi nhánh.</Text>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default CeoCashTodayPage;
